+    <script>
+        const stage = document.querySelector("#stage");
+        const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
+
+        const rain = document.querySelector("#matrix-rain");
+        const context = rain.getContext("2d", {alpha: false});
+        const terminalLines = [...document.querySelectorAll(".terminal__line")];
+        const particleField = document.querySelector("#particle-field");
+        const glyphs = "01010101010101010101010101010101010101010101010101010101GSMG.IO5BTCPUZZLECHALLENGE";
+        let drops = [];
+        let rainFrame = 0;
+        let previousFrame = 0;
+        let rainStarted = false;
+
+        function sizeRain() {
+            const scale = Math.min(window.devicePixelRatio || 1, 2);
+            const width = window.innerWidth;
+            const height = window.innerHeight;
+
+            rain.width = Math.floor(width * scale);
+            rain.height = Math.floor(height * scale);
+            rain.style.width = `${width}px`;
+            rain.style.height = `${height}px`;
+            context.setTransform(scale, 0, 0, scale, 0, 0);
+
+            const fontSize = width < 600 ? 16 : 19;
+            const columns = Math.ceil(width / fontSize);
+            drops = Array.from({length: columns}, (_, column) => ({
+                x: column * fontSize,
+                y: -Math.random() * height,
+                speed: .45 + Math.random() * 1.05,
+                fontSize
+            }));
+
+            context.fillStyle = "#020403";
+            context.fillRect(0, 0, width, height);
+        }
+
+        function drawRain(time) {
+            if (time - previousFrame < 38) {
+                rainFrame = requestAnimationFrame(drawRain);
+                return;
+            }
+
+            previousFrame = time;
+            const width = window.innerWidth;
+            const height = window.innerHeight;
+
+            context.fillStyle = "rgba(2, 4, 3, .12)";
+            context.fillRect(0, 0, width, height);
+            context.textAlign = "center";
+
+            for (const drop of drops) {
+                const glyph = glyphs[Math.floor(Math.random() * glyphs.length)];
+
+                context.font = `${drop.fontSize}px monospace`;
+                context.shadowBlur = 10;
+                context.shadowColor = "rgba(76, 255, 112, .85)";
+                context.fillStyle = Math.random() > .9 ? "#effff2" : "#4cff70";
+                context.fillText(glyph, drop.x, drop.y);
+
+                context.shadowBlur = 0;
+                context.fillStyle = "rgba(46, 177, 76, .78)";
+                context.fillText(glyphs[Math.floor(Math.random() * glyphs.length)], drop.x, drop.y - drop.fontSize);
+
+                drop.y += drop.fontSize * drop.speed;
+
+                if (drop.y > height + 120 && Math.random() > .965) {
+                    drop.y = -Math.random() * height * .7;
+                    drop.speed = .45 + Math.random() * 1.05;
+                }
+            }
+
+            rainFrame = requestAnimationFrame(drawRain);
+        }
+
+        function startRain() {
+            if (rainStarted) {return;}
+            rainStarted = true;
+            sizeRain();
+            rainFrame = requestAnimationFrame(drawRain);
+        }
+
+        function wait(milliseconds) {
+            return new Promise(resolve => window.setTimeout(resolve, milliseconds));
+        }
+
+        function createParticles() {
+            const fragment = document.createDocumentFragment();
+            const viewportRadius = Math.hypot(window.innerWidth, window.innerHeight);
+
+            for (let index = 0; index < 110; index += 1) {
+                const particle = document.createElement("span");
+                const angle = Math.random() * Math.PI * 2;
+                const distance = viewportRadius * (.62 + Math.random() * .52);
+
+                particle.className = "particle";
+                particle.style.setProperty("--x", `${Math.cos(angle) * distance}px`);
+                particle.style.setProperty("--y", `${Math.sin(angle) * distance}px`);
+                particle.style.setProperty("--size", `${1 + Math.random() * 3.5}px`);
+                particle.style.setProperty("--delay", `${Math.random() * .32}s`);
+                fragment.append(particle);
+            }
+
+            particleField.append(fragment);
+        }
+
+        async function typeText(line, text) {
